import type { Product } from '../entities/Product';
import { InsufficientStockError, StockAccountingError, type StockShortage } from '../errors/DomainError';
import type { OrderLine } from '../value-objects/OrderLine';

/** The products an operation works on, keyed by product id. */
export type ProductLookup = ReadonlyMap<string, Product>;

/** Moves stock in and out of reservation for a set of order lines. */
export interface StockAllocator {
  /** Reserves every line, or nothing at all when any product falls short. */
  reserve(lines: readonly OrderLine[], products: ProductLookup): void;
  /** Returns the reserved units of every line to the available pool. */
  release(lines: readonly OrderLine[], products: ProductLookup): void;
  /** Takes the reserved units of every line out of stock. */
  commit(lines: readonly OrderLine[], products: ProductLookup): void;
}

export class StockAllocationService implements StockAllocator {
  reserve(lines: readonly OrderLine[], products: ProductLookup): void {
    const shortages: StockShortage[] = [];
    for (const line of lines) {
      const product = this.productFor(line, products);
      if (!product.canReserve(line.quantity)) {
        shortages.push({
          productId: product.id,
          requested: line.quantity.value,
          available: product.available,
        });
      }
    }
    if (shortages.length > 0) {
      throw new InsufficientStockError(shortages);
    }
    for (const line of lines) {
      this.productFor(line, products).reserve(line.quantity);
    }
  }

  release(lines: readonly OrderLine[], products: ProductLookup): void {
    for (const line of lines) {
      this.productFor(line, products).release(line.quantity);
    }
  }

  commit(lines: readonly OrderLine[], products: ProductLookup): void {
    for (const line of lines) {
      this.productFor(line, products).commit(line.quantity);
    }
  }

  private productFor(line: OrderLine, products: ProductLookup): Product {
    const product = products.get(line.productId);
    if (product === undefined) {
      throw new StockAccountingError(`Product ${line.productId} was not supplied for allocation`);
    }
    return product;
  }
}

